def undo(new, bak):
    t = new
    for k, (old, nw) in enumerate(HUNKS):
        n = len(nw)
        at = [i for i in range(len(t) - n + 1) if t[i:i + n] == nw]
        assert len(at) == 1, ("dec hunk의 새 블록이 새 carry에 정확히 한 번이 아니다", k, len(at))
        t = t[:at[0]] + old + t[at[0] + n:]
    assert t == bak, "dec hunk를 되돌린 carry != pre-dec.bak -- 목록 밖 변경이 있다"
    return t


if __name__ == "__main__":
    new = open(sys.argv[1], "rb").read().split(b"\n")
    bak = open(sys.argv[2], "rb").read().split(b"\n")
    t = undo(new, bak)
    def v3(L):
        s = [i for i, l in enumerate(L) if l.startswith(b'  local v3; v3=$("$PY" -B - "$WT_A/$AUD/attempt1_v3.json"')]
        assert len(s) == 1
        return L[s[0]:s[0] + 1 + L[s[0] + 1:].index(b"EOF")]
    assert v3(new) == v3(bak), "V3 heredoc이 바뀌었다(dec 범위 밖)"
    open(sys.argv[3], "wb").write(b"\n".join(t))
    print("dec 범위 OK: 새 carry = pre-dec.bak + dec hunk %d개(각 1번), V3 heredoc 같음" % len(HUNKS))
